from odoo import fields, models
from odoo.exceptions import UserError


class AccountMove(models.Model):
    _inherit = "account.move"

    petty_cash_fund_id = fields.Many2one(
        "ebshel.petty.cash.fund",
        readonly=True,
        copy=False,
        index="btree_not_null",
        help="Fund whose petty cash document generated this entry.",
    )

    def button_draft(self):
        """An entry generated by a petty cash document is undone from that
        document (which reverses it), never by editing it in place: the
        document and its approvals would no longer describe the books."""
        if not self.env.context.get("petty_cash_bypass") and self.filtered("petty_cash_fund_id"):
            raise UserError(
                self.env._(
                    "This entry was generated by a petty cash document. Cancel the "
                    "document instead: it reverses the entry and keeps the fund history."
                )
            )
        return super().button_draft()
